import re
def config_integer(raw, minimum, maximum):
    if not isinstance(raw,str) or re.fullmatch(r'[0-9]{1,5}',raw) is None:
        raise ValueError('configuration_invalid')
    number=int(raw)
    if not minimum<=number<=maximum:
        raise ValueError('configuration_invalid')
    return number

