import json
def question_bytes(question):
    if not isinstance(question,str) or not question.strip() or len(question)>1000:
        raise ValueError('invalid_request')
    try:
        raw=json.dumps({'question':question},ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    except UnicodeError as error:raise ValueError('invalid_request') from error
    if len(raw)>4096:raise ValueError('invalid_request')
    return raw

def collect_body(chunks, limit):
    result=bytearray()
    for chunk in chunks:
        if not isinstance(chunk,bytes):raise ValueError('invalid_chunk')
        if len(result)+len(chunk)>limit:raise ValueError('request_too_large')
        result.extend(chunk)
    return bytes(result)

