import math
def unit_vector(values):
    if not isinstance(values,(list,tuple)) or len(values)!=32:
        raise ValueError('vector_invalid')
    if any(type(x) not in (int,float) or not -1000000<=x<=1000000 for x in values):
        raise ValueError('vector_invalid')
    norm=math.hypot(*values)
    return tuple(float(x/norm) for x in values) if norm else ()

def vector_candidates(rows, tenant, verified_ids, contract, limit):
    eligible=[r for r in rows if r['tenant']==tenant and r['chunk_id'] in verified_ids and r['embedding_contract']==contract]
    return [r['chunk_id'] for r in sorted(eligible,key=lambda r:(r['distance'],r['chunk_id']))[:limit]]

import copy
import hashlib
import json
def snapshot_digest(chunks, policies, contract):
    normalized=copy.deepcopy(policies)
    normalized.sort(key=lambda p:(p['tenant'],p['document'],p['version']))
    for policy in normalized:policy['readers'].sort()
    raw=json.dumps({'embedding':contract,'chunks':chunks,'policies':normalized},sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False)
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()

def cache_write(entries, key, result, now, ttl, capacity):
    if result['reason']!='ok':return None
    entries[key]=(now+ttl,result)
    entries.move_to_end(key)
    while len(entries)>capacity:entries.popitem(last=False)
    return None

import math
def window_step(state, now, limit):
    window=int(now//60)
    count=state[1] if state is not None and state[0]==window else 0
    if count>=limit:
        return (window,count),max(1,math.ceil((window+1)*60-now))
    return (window,count+1),0

import json
def sse_frame(event, payload):
    if not isinstance(event,str) or event not in ('meta','result','done'):
        raise ValueError('event_invalid')
    data=json.dumps(payload,ensure_ascii=False,separators=(',',':'),allow_nan=False)
    return 'event: '+event+'\n'+'data: '+data+'\n\n'

def stream_complete(frames, request_id):
    if len(frames)!=3 or [event for event,_ in frames]!=['meta','result','done']:
        return False
    if any(payload.get('request_id')!=request_id for _,payload in frames):
        return False
    return (frames[0][1].get('mode')=='validated-result'
            and frames[1][1].get('status') in ('answered','refused')
            and frames[2][1].get('complete') is True)

