import copy
def seed_merge(existing, incoming):
    for key,value in incoming.items():
        if key in existing and existing[key]!=value:raise ValueError('seed_conflict')
    merged=copy.deepcopy(existing)
    for key,value in incoming.items():
        if key not in merged:merged[key]=copy.deepcopy(value)
    return merged

